with base as (select *, cast(is_active as int) as is_active_flag from customers where signup_date >= date '2023-03-06' and segment is not null) select id, country, segment, signup_date, is_active, credit_limit, age, is_active_flag, lag(is_active_flag, 1) over w_hist as prev_is_active_flag, lead(credit_limit, 2, 0) over w_recent as next_credit_limit, corr(credit_limit, age) over (partition by segment) as corr_credit_limit_age, first_value(credit_limit, true) over (partition by segment order by is_active_flag, id rows between unbounded preceding and current row) as first_known_credit_limit from base window w_hist as (order by credit_limit, id), w_recent as (partition by segment order by is_active_flag, id);
